-- 세 표기를 나란히 쓴다

@Test
void 세_표기() {
    em.clear();
    System.out.println("--- 풀네임 ---");
    queryFactory.selectFrom(QMember.member)
            .where(QMember.member.username.eq("m1")).fetch();

    em.clear();
    System.out.println("--- static import ---");
    queryFactory.selectFrom(member)
            .where(member.username.eq("m1")).fetch();

    em.clear();
    System.out.println("--- 새 별칭 ---");
    QMember m2 = new QMember("m2");
    queryFactory.selectFrom(m2)
            .where(m2.username.eq("m1")).fetch();
}

--- 풀네임 ---
/* select member1 from Member member1 where member1.username = ?1 */
Hibernate: select ... from member m1_0 where m1_0.username=?
--- static import ---
/* select member1 from Member member1 where member1.username = ?1 */
Hibernate: select ... from member m1_0 where m1_0.username=?
--- 새 별칭 ---
/* select m2 from Member m2 where m2.username = ?1 */
Hibernate: select ... from member m1_0 where m1_0.username=?

--   앞 둘은 완전히 같다
--   셋째만 JPQL 별칭이 다르다
--   SQL 은 셋 다 같다


-- 정적 인스턴스는 하나다

@Test
void 같은_객체() {
    System.out.println("같나: " + (member == QMember.member));
    System.out.println("해시: " + System.identityHashCode(member));
    System.out.println("해시: " + System.identityHashCode(QMember.member));
}

같나: true
해시: 1204718332
해시: 1204718332

--   import 는 이름만 짧게 한 것이다


-- 새로 만들면 다른 객체다

@Test
void 새_객체() {
    QMember a = new QMember("m2");
    QMember b = new QMember("m2");
    System.out.println("같나: " + (a == b));
    System.out.println("별칭: " + a.getMetadata().getName());
}

같나: false
별칭: m2

--   객체는 다르고 별칭은 같다


-- 자기 조인에는 둘이 필요하다

@Test
void 자기_조인() {
    QMember older = new QMember("older");

    em.clear();
    List<Tuple> rows = queryFactory
            .select(member.username, older.username)
            .from(member, older)
            .where(member.age.lt(older.age),
                   member.team.eq(older.team))
            .fetch();

    rows.forEach(t -> System.out.println(
            t.get(member.username) + " < " + t.get(older.username)));
}

