-- 하나로 하면 이상해진다

@Test
void 하나로() {
    em.clear();
    List<Tuple> rows = queryFactory
            .select(member.username, member.username)
            .from(member, member)                 // 같은 것을 두 번
            .where(member.age.lt(member.age))
            .fetch();
    System.out.println("건수: " + rows.size());
}

