-- 두 번 타면 조인도 두 번인가

@Test
void 두_번_타기() {
    em.clear();
    queryFactory.selectFrom(member)
            .where(member.team.name.eq("teamA")
                    .or(member.team.name.eq("teamB")))
            .fetch();
}

/* select
    member1
from
    Member member1
  inner join
    member1.team as team
where
    team.name = ?1
    or team.name = ?2 */

Hibernate:
    select ... from member m1_0
    join team t1_0 on t1_0.team_id=m1_0.team_id
    where t1_0.name=? or t1_0.name=?

--   조인은 한 번이다
--   ⑭ 8.1절의 명세와 다르다
--   거기선 조각마다 join 을 불러 두 번 붙었다


-- import 를 안 하면 길어진다

@Test
void import_없이() {
    em.clear();
    queryFactory
            .select(QMember.member.username, QTeam.team.name)
            .from(QMember.member)
            .join(QMember.member.team, QTeam.team)
            .where(QTeam.team.name.eq("teamA"))
            .fetch();
}

